+  var cw = p.CircularDirection === "CW";
+  if (cw === spinRev) {
+    refuse("thread half-turn turns " + (cw ? "clockwise" : "counter-clockwise") + " seen from +Z but the spindle runs " + (spinRev ? "M04" : "M03") + " - it would cut the other hand; regenerate the thread");
