+#[test]
+fn an_axial_drill_posts_as_plain_moves_in_mm_and_inch() {
+    for (inch, file) in [(false, "axial_drill_mm"), (true, "axial_drill_inch")] {
+        let (world, _history) = drill_world(inch);
