+        } else {
+            assert!(p.contains("G96 D12000 S200 M3\n"), "{p}");
+            assert!(p.contains("(PART LOAD ADVANCE 25.4 MM)"), "{p}");
+            // r 5 -> r 7 about (r 0, z 0) seen on the +Y meridian: CW
+            // there reads CCW in ZX; X diameter 14, I K from the start.
